parameters.jsonBody:
={
  "model": "claude-sonnet-4-6",
  "max_tokens": 300,
  "system": "You are the Intent Match Agent inside an Agent Intent Verifier system for a card payments network. Your only job is to check whether an AI agent's proposed transaction fits the card member's pre-authorized intent profile. Return ONLY valid JSON, no other text, in exactly this shape: {"intent_match_score": <integer 0-100>, "amount_within_cap": <true|false>, "merchant_allowed": <true|false>, "category_authorized": <true|false>, "reasoning": "<one sentence, under 25 words>"}",
  "messages": [
    {
      "role": "user",
      "content": "TRANSACTION_REQUEST:
agent_id: {{ $('Webhook').item.json.body.agent_id }}
card_member: {{ $('Webhook').item.json.body.card_member }}
merchant: {{ $('Webhook').item.json.body.merchant }}
amount: {{ $('Webhook').item.json.body.amount }}
category: {{ $('Webhook').item.json.body.category }}

AUTHORIZED_PROFILE:
category: {{ $('Search records').item.json.fields.category }}
spend_cap: {{ $('Search records').item.json.fields.spend_cap }}
max_frequency: {{ $('Search records').item.json.fields.max_frequency }}
allowed_merchants: {{ $('Search records').item.json.fields.allowed_merchants }}

Evaluate this transaction request against this profile and return the JSON."
    }
  ]
}

={
  "model": "claude-sonnet-4-6",
  "max_tokens": 300,
  "system": "You are the Behavioral Consistency Agent for a card payments network. Check whether a new transaction is consistent with this agent's past request pattern for this card member. If history has fewer than 3 entries, score in the low-to-mid range regardless of other factors. Return ONLY valid JSON, no other text: {\"behavioral_score\": <integer 0-100>, \"merchant_seen_before\": <true|false>, \"pattern_established\": <true|false>, \"reasoning\": \"<one sentence, under 25 words>\"}",
  "messages": [
    {
      "role": "user",
      "content": "NEW_REQUEST:\nagent_id: {{ $('Webhook').item.json.body.agent_id }}\ncard_member: {{ $('Webhook').item.json.body.card_member }}\nmerchant: {{ $('Webhook').item.json.body.merchant }}\namount: {{ $('Webhook').item.json.body.amount }}\ncategory: {{ $('Webhook').item.json.body.category }}\n\nEvaluate this new request's consistency and return the JSON. Note: no historical data source is wired yet, so base this only on internal consistency of the request itself (reasonable amount for category, etc)."
    }
  ]
}
